 :root{--gold:#d8b979;--cream:#ece5d7;--muted:#a19b90;--red:#a63832}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#090b0d;color:var(--cream);font-family:'DM Sans',sans-serif}canvas{display:block;width:100%;height:100%}.game{position:fixed;inset:0}.shade{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 48%,transparent 42%,#04050755 100%),linear-gradient(180deg,#05070977,transparent 24%,transparent 64%,#050709aa)}
