n:absolute;bottom:30px;left:34px;display:flex;gap:12px;align-items:center}.flask{width:43px;height:49px;position:relative;border:1px solid #d8b97988;background:#171615dd;display:grid;place-items:center;color:#e5c779;font:19px Cinzel,serif;box-shadow:0 4px 18px #0007}.flask small{position:absolute;bottom:3px;right:5px;font:9px 'DM Sans';color:#ddd}.weapon{font:11px Cinzel,serif;letter-spacing:.12em;text-shadow:0 2px 5px #000}.weapon small{display:block;margin-top:4px;color:#aaa;font:9px 'DM Sans';letter-spacing:.1em}.controls{position:absolute;bottom:29px;right:32px;text-align:right;color:#c5bdaf;font-size:10px;line-height:1.9;text-shadow:0 2px 6px #000}.key{display:inline-block;min-width:19px;padding:0 4px;margin:0 2px;border:1px solid #c5bdaf66;color:#eadbb7;text-align:center;font-size:9px}
